[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "project-status-report-surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateDataModel": {
      "surfaceId": "project-status-report-surface",
      "value": {
        "tasks": [
          {
            "id": "task1",
            "name": "UI Mockups",
            "status": "Completed",
            "progress": 1.0,
            "icon": "check-circle",
            "iconColor": "success"
          },
          {
            "id": "task2",
            "name": "Backend API",
            "status": "In Progress",
            "progress": 0.6,
            "icon": "gear",
            "iconColor": "primary"
          },
          {
            "id": "task3",
            "name": "Content Migration",
            "status": "Not Started",
            "progress": 0.0,
            "icon": "clock",
            "iconColor": "neutral"
          },
          {
            "id": "task4",
            "name": "QA Testing",
            "status": "Blocked by Backend",
            "progress": 0.0,
            "icon": "stop-circle",
            "iconColor": "danger"
          }
        ]
      }
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "project-status-report-surface",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "spacing": "medium"
          },
          "children": [
            "header_col",
            "summary_card",
            "tasks_card",
            "health_alert",
            "bottleneck_card",
            "actions_title",
            "actions_row"
          ]
        },
        {
          "id": "header_col",
          "type": "Column",
          "properties": {
            "spacing": "extraSmall"
          },
          "children": [
            "title_text",
            "date_text"
          ]
        },
        {
          "id": "title_text",
          "type": "Text",
          "properties": {
            "text": "Project Status Report: Website Redesign",
            "style": "title"
          }
        },
        {
          "id": "date_text",
          "type": "Text",
          "properties": {
            "text": "Date: 2024-03-01",
            "style": "caption"
          }
        },
        {
          "id": "summary_card",
          "type": "Card",
          "children": [
            {
              "id": "summary_col",
              "type": "Column",
              "properties": {
                "spacing": "small"
              },
              "children": [
                {
                  "id": "summary_title",
                  "type": "Text",
                  "properties": {
                    "text": "Summary",
                    "style": "heading"
                  }
                },
                {
                  "id": "summary_text",
                  "type": "Text",
                  "properties": {
                    "text": "The 'Website Redesign' project is currently facing significant challenges. While UI Mockups are complete, the critical Backend API development is only 60% complete, directly blocking QA Testing. Content Migration has not yet started."
                  }
                }
              ]
            }
          ]
        },
        {
          "id": "tasks_card",
          "type": "Card",
          "children": [
            {
              "id": "tasks_col",
              "type": "Column",
              "properties": {
                "spacing": "medium"
              },
              "children": [
                {
                  "id": "tasks_title",
                  "type": "Text",
                  "properties": {
                    "text": "Task Status Overview",
                    "style": "heading"
                  }
                },
                {
                  "id": "tasks_list",
                  "type": "List",
                  "properties": {
                    "childrenBinding": "tasks"
                  },
                  "templateChild": "task_item_template"
                }
              ]
            }
          ]
        },
        {
          "id": "task_item_template",
          "type": "Row",
          "properties": {
            "spacing": "medium",
            "verticalAlignment": "center"
          },
          "children": [
            {
              "id": "task_icon",
              "type": "Icon",
              "properties": {
                "name": "{{ item.icon }}",
                "color": "{{ item.iconColor }}"
              }
            },
            {
              "id": "task_info_col",
              "type": "Column",
              "properties": {
                "horizontalAlignment": "start",
                "weight": 1
              },
              "children": [
                {
                  "id": "task_name",
                  "type": "Text",
                  "properties": {
                    "text": "{{ item.name }}",
                    "weight": "bold"
                  }
                },
                {
                  "id": "task_status",
                  "type": "Text",
                  "properties": {
                    "text": "{{ item.status }}",
                    "style": "caption"
                  }
                }
              ]
            },
            {
              "id": "task_progress",
              "type": "ProgressBar",
              "properties": {
                "value": "{{ item.progress }}",
                "width": "120px"
              }
            }
          ]
        },
        {
          "id": "health_alert",
          "type": "Alert",
          "properties": {
            "title": "Project Health Status: At Risk",
            "description": "The project is at risk due to key dependencies not being met and a major component still in progress. The inability to start QA Testing and Content Migration significantly impacts the project timeline.",
            "variant": "danger"
          }
        },
        {
          "id": "bottleneck_card",
          "type": "Card",
          "children": [
            {
              "id": "bottleneck_col",
              "type": "Column",
              "properties": {
                "spacing": "small"
              },
              "children": [
                {
                  "id": "bottleneck_title",
                  "type": "Text",
                  "properties": {
                    "text": "Primary Bottleneck: Backend API Development",
                    "style": "heading"
                  }
                },
                {
                  "id": "bottleneck_text",
                  "type": "Text",
                  "properties": {
                    "text": "The Backend API development is the primary bottleneck. Its incomplete status (60%) is directly blocking the QA Testing phase. Until the Backend API is finalized, further progress on testing and potentially other dependent tasks like Content Migration cannot proceed efficiently."
                  }
                }
              ]
            }
          ]
        },
        {
          "id": "actions_title",
          "type": "Text",
          "properties": {
            "text": "Quick Actions",
            "style": "heading"
          }
        },
        {
          "id": "actions_row",
          "type": "Row",
          "properties": {
            "spacing": "small"
          },
          "children": [
            "action_btn_1",
            "action_btn_2",
            "action_btn_3"
          ]
        },
        {
          "id": "action_btn_1",
          "type": "Button",
          "properties": {
            "label": "Update Backend API Status",
            "action": {
              "type": "functionCall",
              "call": "openUrl",
              "arguments": {
                "url": "https://example.com/project/websiteredesign/backend_status_update"
              }
            }
          }
        },
        {
          "id": "action_btn_2",
          "type": "Button",
          "properties": {
            "label": "Review Backend API Development Plan",
            "action": {
              "type": "functionCall",
              "call": "openUrl",
              "arguments": {
                "url": "https://example.com/project/websiteredesign/backend_plan"
              }
            }
          }
        },
        {
          "id": "action_btn_3",
          "type": "Button",
          "properties": {
            "label": "Discuss Content Migration Readiness",
            "action": {
              "type": "functionCall",
              "call": "openUrl",
              "arguments": {
                "url": "https://example.com/project/websiteredesign/content_migration_planning"
              }
            }
          }
        }
      ]
    }
  }
]
